class LmdbVariableGraphPointTest {
	private static final String POINT = "SELECT ?g { GRAPH ?g { <urn:s> <urn:p> ?o } }";

	@Test
	void singlePatternPreservesGraphIdentityMultiplicityAndSnapshot(@TempDir File directory) {
		var store = new LmdbStore(directory, new LmdbStoreConfig().setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false));
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var s = vf.createIRI("urn:s");
			var p = vf.createIRI("urn:p");
			var g = vf.createIRI("urn:g");
			var b = vf.createBNode("named-graph");
			connection.begin();
			for (var context : List.of(g, b, RDF4J.NIL)) {
				connection.add(s, p, s, context);
				connection.add(s, p, g, context);
			}
			connection.commit();

			var query = connection.prepareTupleQuery(POINT);
			assertThat(graphs(query)).containsExactlyInAnyOrder(g, g, b, b, RDF4J.NIL, RDF4J.NIL);
			query.setBinding("g", b);
			assertThat(graphs(query)).containsExactly(b, b);
			query.clearBindings();
			var shared = connection.prepareTupleQuery("SELECT ?g { GRAPH ?g { <urn:s> <urn:p> ?g } }");
			assertThat(graphs(shared)).containsExactly(g);

			connection.begin(IsolationLevels.SNAPSHOT);
			connection.clear(g);
			connection.add(s, p, vf.createLiteral("default-only"), (Resource) null);
			assertThat(graphs(query)).containsExactlyInAnyOrder(b, b, RDF4J.NIL, RDF4J.NIL);
			connection.commit();
			assertThat(graphs(query)).containsExactlyInAnyOrder(b, b, RDF4J.NIL, RDF4J.NIL);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void inferredPlaneAndExplicitDatasetRemainAuthoritative(@TempDir File directory) {
		var store = new LmdbStore(directory, new LmdbStoreConfig().setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false));
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var s = vf.createIRI("urn:s");
			var p = vf.createIRI("urn:p");
			var e = vf.createIRI("urn:explicit");
			var i = vf.createIRI("urn:inferred");
			connection.begin();
			connection.add(s, p, s, e);
			((LmdbStoreConnection) connection.getSailConnection()).addInferredStatement(s, p, s, i);
			connection.commit();
			var query = connection.prepareTupleQuery(POINT);
			query.setIncludeInferred(true);
			assertThat(graphs(query)).containsExactlyInAnyOrder(e, i);
			query.setIncludeInferred(false);
			assertThat(graphs(query)).containsExactly(e);
			var onlyInferredGraph = connection
					.prepareTupleQuery("SELECT ?g FROM NAMED <urn:inferred> { GRAPH ?g { <urn:s> <urn:p> ?o } }");
			assertThat(graphs(onlyInferredGraph)).containsExactly(i);
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void closeOrCancelWhileOpeningNeverPullsTheNewChild(boolean cancel) throws Exception {
		var opening = new CountDownLatch(1);
		var resume = new CountDownLatch(1);
		var pulls = new AtomicInteger();
		var closes = new AtomicInteger();
		try (var executor = Executors.newSingleThreadExecutor();
				var rows = LmdbEvaluationStrategy.demandGraphLookup(input -> {
					opening.countDown();
					try {
						if (!resume.await(10, TimeUnit.SECONDS)) {
							throw new AssertionError("opener was not released");
						}
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new AssertionError(e);
					}
					return new CloseableIteration<BindingSet>() {
						@Override
						public boolean hasNext() {
							pulls.incrementAndGet();
							return false;
						}

						@Override
						public BindingSet next() {
							throw new AssertionError();
						}

						@Override
						public void remove() {
							throw new UnsupportedOperationException();
						}

						@Override
						public void close() {
							closes.incrementAndGet();
						}
					};
				}, EmptyBindingSet.getInstance())) {
			var first = executor.submit(rows::hasNext);
			try {
				assertThat(opening.await(10, TimeUnit.SECONDS)).isTrue();
				if (cancel) {
					assertThat(CooperativeCancellation.forward(rows)).isTrue();
				} else {
					rows.close();
				}
			} finally {
				resume.countDown();
			}
			assertThat(first.get(10, TimeUnit.SECONDS)).isFalse();
			assertThat(pulls).hasValue(0);
			assertThat(closes).hasValue(1);
		}
	}

	private static List<Value> graphs(TupleQuery query) {
		List<BindingSet> saved = new ArrayList<>();
		try (var rows = query.evaluate()) {
			while (rows.hasNext()) {
				saved.add(rows.next());
			}
		}
		return saved.stream().map(row -> row.getValue("g")).toList();
	}
}
